const msg = $json;
const binary = $binary ?? {};

const MAILBOX_ID = 'avisarnoam1@gmail.com';

// --------------------------------------------------
// Sender
// --------------------------------------------------

let sender = null;

if (msg.from?.text) {
  sender = msg.from.text;
} else if (msg.from?.value?.length) {
  const firstSender = msg.from.value[0];

  sender = firstSender.name
    ? `${firstSender.name} <${firstSender.address}>`
    : firstSender.address;
}

// --------------------------------------------------
// Subject
// --------------------------------------------------

const subject = msg.subject ?? null;

// --------------------------------------------------
// Received date
// --------------------------------------------------

let receivedAt = null;

if (msg.date) {
  const parsedDate = new Date(msg.date);

  if (!Number.isNaN(parsedDate.getTime())) {
    receivedAt = parsedDate.toISOString();
  }
}

// --------------------------------------------------
// Body
// Prefer text/plain. Fall back to HTML.
// --------------------------------------------------

let textBody = '';

if (typeof msg.text === 'string' && msg.text.trim()) {
  textBody = msg.text.trim();
} else if (typeof msg.html === 'string' && msg.html.trim()) {
  textBody = msg.html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+\n/g, '\n')
    .replace(/\n\s+/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

// --------------------------------------------------
// Attachments from n8n binary data
// --------------------------------------------------

const attachmentSources = Object.entries(binary).map(
  ([binaryPropertyName, file]) => {

    const attachmentId =
      `${msg.id ?? 'unknown'}:${binaryPropertyName}`;

    return {
      attachment_id: attachmentId,

      // Internal n8n field.
      // This is NOT sent inside EmailEnvelope.
      binary_property: binaryPropertyName,

      filename: file.fileName ?? null,
      mime_type:
        file.mimeType ?? 'application/octet-stream',

      // Debug only.
      file_size: file.fileSize ?? null,
    };
  }
);

// --------------------------------------------------
// EmailEnvelope sent to /triage
// --------------------------------------------------

const emailEnvelope = {
  mailbox_id: MAILBOX_ID,
  message_id: msg.id ?? null,
  thread_id: msg.threadId ?? null,
  received_at: receivedAt,
  sender,
  subject,
  text_body: textBody,

  attachments: attachmentSources.map(a => ({
    filename: a.filename,
    mime_type: a.mime_type,
    attachment_id: a.attachment_id,
  })),
};

return {
  json: {
    email_envelope: emailEnvelope,

    // Internal workflow helper.
    // POST /triage does not receive this object.
    attachment_sources: attachmentSources,
  },

  // Keep the downloaded PDF alive.
  binary,
};

// Get normalized attachment metadata.
const normalizedNode =
  $('Normalize Gmail Message').item;

const envelope =
  normalizedNode.json.email_envelope;

const attachmentSources =
  normalizedNode.json.attachment_sources ?? [];

// Get the actual binary files from Gmail.
const gmailItem =
  $('Get Full Message').item;

const binary =
  gmailItem.binary ?? {};

// --------------------------------------------------
// Find PDFs
// --------------------------------------------------

const pdfs = attachmentSources.filter(a => {
  const mimeType =
    String(a.mime_type ?? '').toLowerCase();

  const filename =
    String(a.filename ?? '').toLowerCase();

  return (
    mimeType === 'application/pdf' ||
    filename.endsWith('.pdf')
  );
});

// --------------------------------------------------
// We require EXACTLY ONE PDF.
// --------------------------------------------------

if (pdfs.length !== 1) {
  return {
    json: {
      ready: false,
      reason:
        `expected_exactly_one_pdf_found_${pdfs.length}`,
      pdf_count: pdfs.length,
      binary_properties_found:
        Object.keys(binary),
    }
  };
}

const pdf = pdfs[0];

// Make sure the corresponding binary actually exists.
if (!binary[pdf.binary_property]) {
  return {
    json: {
      ready: false,
      reason: 'pdf_metadata_found_but_binary_missing',
      pdf_count: 1,
      binary_property: pdf.binary_property,
      binary_properties_found:
        Object.keys(binary),
    }
  };
}

// --------------------------------------------------
// Success
// --------------------------------------------------

return {
  json: {
    ready: true,
    pdf_count: 1,

    message_id:
      envelope.message_id,

    attachment_id:
      pdf.attachment_id,

    filename:
      pdf.filename,

    mime_type:
      pdf.mime_type,

    binary_property:
      pdf.binary_property,
  },

  // Pass the real PDF into the next nodes.
  binary,
};

const binaryProperty = $json.binary_property;

if (!binaryProperty) {
  throw new Error(
    'binary_property is missing'
  );
}

if (!$binary?.[binaryProperty]) {
  throw new Error(
    `Binary property "${binaryProperty}" is missing`
  );
}

// Read the actual PDF bytes from n8n binary storage
const buffer =
  await this.helpers.getBinaryDataBuffer(
    0,
    binaryProperty
  );

if (!buffer || buffer.length === 0) {
  throw new Error(
    'PDF binary buffer is empty'
  );
}

// Demo limit: 10 MiB after decoding
const MAX_PDF_BYTES =
  10 * 1024 * 1024;

if (buffer.length > MAX_PDF_BYTES) {
  throw new Error(
    `PDF exceeds 10 MiB demo limit: ${buffer.length} bytes`
  );
}

// Convert raw PDF bytes to standard Base64
const contentBase64 =
  buffer.toString('base64');

// Temporary M2 opportunity ID.
// M7 will replace this with the final stable hash.
const opportunityId =
  `m2_${$json.message_id}`;

return {
  json: {
    opportunity_id:
      opportunityId,

    attachment_id:
      $json.attachment_id,

    filename:
      $json.filename,

    mime_type:
      $json.mime_type,

    content_base64:
      contentBase64,

    decoded_size_bytes:
      buffer.length,
  }
};
